{
 "summary": "The file defines the k-colour triangle Ramsey number R_k(3) as the least n such that every k-colouring of K_n has a monochromatic triangle. It then states four consequences of the paper's result: R_k(3)^{1/k} → ∞, log R_k ~ k log k up to the constants 1/3 and 1, and log R_k = Θ(k log k). The main caveat is that `erdos_problem_183_explicit` has the false hypothesis `(1:ℕ)=0`, so it is vacuously true and says nothing about the explicit lower bound. Theorem 1.1 itself (existence of c with R_k(3) ≥ (c k^{1/3}/log k)^k for all k ≥ 2) has no faithful non-vacuous formalization.",
 "glossary": [
  {"decl": "TriangleFree", "line": 8, "plain": "A k-edge-colouring C of K_n has no monochromatic triangle: each colour class graph is K_3-free.", "standard_concept": "triangle-free (no monochromatic triangle) k-colouring of K_n", "matches_standard": "yes", "note": ""},
  {"decl": "ForcesMonochromaticTriangle", "line": 12, "plain": "Every k-colouring of the edges of K_n contains a monochromatic triangle.", "standard_concept": "n ≥ R_k(3)", "matches_standard": "yes", "note": "For k = 0 and n ≥ 2 there are no labelings, so the statement holds vacuously and gives junk R_0 = 2. This is irrelevant to the asymptotic statements."},
  {"decl": "triangleRamseyNumber", "line": 15, "plain": "R_k(3) = least n such that every k-colouring of K_n has a monochromatic triangle.", "standard_concept": "multicolour Ramsey number R(3,…,3) with k colours", "matches_standard": "yes", "note": "sInf junk value 0 only arises if the set is empty. The set is nonempty by the factorial upper bound."}
 ],
 "lean_claims": [
  {"theorem": "erdos_183", "line": 18, "plain": "As k → ∞, R_k(3)^{1/k} → +∞."},
  {"theorem": "erdos_problem_183_explicit", "line": 25, "plain": "Assuming the false hypothesis 1 = 0 (in ℕ), the following holds. For all k ≥ 2, ((1/(6e^38))·k^{1/3}/log k)^k ≤ R_k(3), and R_k(3)^{1/k} → ∞. This is vacuous."},
  {"theorem": "triangleRamseyNumber_log_sharp_coefficients", "line": 36, "plain": "For every ε > 0, for all sufficiently large k, (1/3 − ε)·k·log k ≤ log R_k(3) ≤ (1+ε)·k·log k."},
  {"theorem": "triangleRamseyNumber_log_isTheta", "line": 45, "plain": "log R_k(3) = Θ(k log k) as k → ∞."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "There is an absolute constant c > 0 such that for every k ≥ 2, R_k(3) ≥ (c k^{1/3}/log k)^k."},
  {"ref": "Theorem 1.1 (consequences)", "plain": "Combined with the factorial upper bound (2), k^{(1/3−o(1))k} ≤ R_k(3) ≤ k^{(1+o(1))k}, so R_k(3) = k^{Θ(k)}."},
  {"ref": "Eq. (4)", "plain": "lim R_k(3)^{1/k} = +∞."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1 (explicit lower bound for all k ≥ 2)", "lean_theorem": "erdos_problem_183_explicit", "relation": "not_formalized", "why": "The statement is guarded by the false hypothesis (1:ℕ)=0, so it carries no content. The explicit constant 1/(6e^38) is also not in the excerpt. No unconditional existence statement of c is formalized."},
  {"paper_ref": "R_k(3) = k^{Θ(k)} / k^{(1/3−o(1))k} ≤ R_k(3) ≤ k^{(1+o(1))k}", "lean_theorem": "triangleRamseyNumber_log_sharp_coefficients", "relation": "equivalent", "why": "The ε-form with log is the standard reading of the o(1) exponents. It is unconditional."},
  {"paper_ref": "R_k(3) = k^{Θ(k)}", "lean_theorem": "triangleRamseyNumber_log_isTheta", "relation": "equivalent", "why": "log R_k = Θ(k log k) is equivalent to R_k = k^{Θ(k)}."},
  {"paper_ref": "Eq. (4)", "lean_theorem": "erdos_183", "relation": "equivalent", "why": "The statement is exactly that R_k(3)^{1/k} tends to infinity."}
 ],
